    def create_main_layout(self):
        main_container = ttk.Frame(self.root)
        main_container.pack(fill=tk.BOTH, expand=True)
        
        left_panel = ttk.Frame(main_container, width=380)
        left_panel.pack(side=tk.LEFT, fill=tk.BOTH, padx=5, pady=5)
        left_panel.pack_propagate(False)
        
        right_panel = ttk.Frame(main_container)
        right_panel.pack(side=tk.RIGHT, fill=tk.BOTH, expand=True, padx=5, pady=5)
        
        self.input_panels = InputPanels(left_panel, self.on_calculate)
        self.input_panels.view_change_callback = self.on_view_change
        self.input_panels.results_window_callback = self.show_results_window
        self.input_panels.shape_analysis_callback = self.on_given_shape_analysis
        
        canvas_frame = ttk.Frame(right_panel)
        canvas_frame.pack(side=tk.TOP, fill=tk.BOTH, expand=True)
        self.canvas = NozzleCanvas(canvas_frame)
        self.input_panels.canvas_ref = self.canvas
        
        def update_colorbar_limits():
            params = self.input_panels.get_parameters()
            self.canvas.colorbar_min = params.get('colorbar_min', 0)
            self.canvas.colorbar_max = params.get('colorbar_max', 3)
            if self.current_results and self.input_panels.view_mode_var.get() in [DISPLAY_MACH, DISPLAY_PRESSURE, DISPLAY_TEMP]:
                try:
                    view_mode = self.input_panels.view_mode_var.get()
                    X, Y, Z = self.moc_engine.get_contour_data(variable=view_mode)
                    self.canvas.plot_contour(X, Y, Z, variable=view_mode)
                except:
                    pass
        
        self.input_panels.colorbar_min.trace_add('write', lambda *args: update_colorbar_limits())
        self.input_panels.colorbar_max.trace_add('write', lambda *args: update_colorbar_limits())
    
    def create_status_bar(self):
        self.status_bar = ttk.Label(self.root, text="Ready", relief=tk.SUNKEN, anchor=tk.W)
        self.status_bar.pack(side=tk.BOTTOM, fill=tk.X)
    
    def on_view_change(self, view_mode):
        if self.current_results is None:
            return
        
        if view_mode == DISPLAY_GEOMETRY:
            self.canvas.plot_nozzle_geometry(self.current_results, show_characteristics=True)
        
        elif view_mode in [DISPLAY_MACH, DISPLAY_PRESSURE, DISPLAY_TEMP]:
            try:
                X, Y, Z = self.moc_engine.get_contour_data(variable=view_mode)
                self.canvas.plot_contour(X, Y, Z, variable=view_mode)
            except Exception as e:
                messagebox.showerror("Contour Error", f"Failed to create contour:\n{str(e)}")
    
    def on_calculate(self, params):
        try:
            self.status_bar.config(text="Calculating...")
            self.root.update()
            
            self.moc_engine = MOCEngine(gamma=params['gamma'])

            # Zone method configuration
            if params.get('use_zone_method', False):
                self.moc_engine.use_zone_method = True
                adjusted_rays = max(10, params['num_rays'] // 2)  # Faster zone calculation
            else:
                self.moc_engine.use_zone_method = False
                adjusted_rays = params['num_rays']  # Full point-by-point accuracy

            print(f"DEBUG: Calculation mode = {'ZONE' if params.get('use_zone_method') else 'POINTS'}, rays = {adjusted_rays}")

            problem_type = params.get('problem_type', 1)
            
            
            if problem_type == 1:
                results = self.moc_engine.calculate_2d_ideal_nozzle(
                    mach_exit=params['mach_exit'],
                    num_rays=adjusted_rays,
                    throat_height=params['throat_height']
                )
            elif problem_type == 2:
                results = self.moc_engine.calculate_axisymmetric_nozzle(
                    mach_exit=params['mach_exit'],
                    num_rays=adjusted_rays,
                    throat_radius=params['throat_height']
                )
            elif problem_type == 3:
                results = self.moc_engine.calculate_plug_nozzle(
                    mach_exit=params['mach_exit'],
                    num_rays=adjusted_rays,
                    throat_radius=params['throat_height'],
                    spike_length_ratio=0.8
                )
            elif problem_type == 4:
                results = self.moc_engine.calculate_cone_nozzle(
                    mach_exit=params['mach_exit'],
                    num_rays=adjusted_rays,
                    throat_radius=params['throat_height'],
                    cone_half_angle=15.0
                )
            elif problem_type == 5:
                results = self.moc_engine.calculate_wedge_nozzle(
                    mach_exit=params['mach_exit'],
                    num_rays=adjusted_rays,
                    throat_height=params['throat_height'],
                    wedge_angle=12.0
                )
            elif problem_type == 6:
                results = self.moc_engine.calculate_bell_nozzle(
                    mach_exit=params['mach_exit'],
                    num_rays=adjusted_rays,
                    throat_radius=params['throat_height'],
                    bell_contraction_ratio=0.8,
                    bell_length_ratio=0.8
                )
            elif problem_type == 7:
                results = self.moc_engine.calculate_truncated_ideal_nozzle(
                    mach_exit=params['mach_exit'],
                    num_rays=adjusted_rays,
                    throat_height=params['throat_height'],
                    truncation_ratio=0.75
                )
            elif problem_type == 8:
                results = self.moc_engine.calculate_minimum_length_nozzle(
                    mach_exit=params['mach_exit'],
                    num_rays=adjusted_rays,
                    throat_radius=params['throat_height']
                )
            elif problem_type == 9:
                results = self.moc_engine.calculate_throat_expansion_nozzle(
                    mach_exit=params['mach_exit'],
                    num_rays=adjusted_rays,
                    throat_radius=params['throat_height'],
                    expansion_angle=45.0
                )
            else:
                raise ValueError(f"Unknown problem type: {problem_type}")
            
           # Calculate plume if enabled
            if 'plume_enabled' in params and params['plume_enabled']:
                try:
                    plume_mode = params.get('plume_mode', 1)
                    p_ambient = params.get('p_ambient', 14.7)
                    
                    print(f"DEBUG: Plume mode = {plume_mode}")  
                    
                    if plume_mode == 0:
                        # No plume
                        pass
                    elif plume_mode == 1:
                        # Simple plume
                        print("DEBUG: Calling simple plume")  
                        plume_data = self.moc_engine.calculate_simple_plume(p_ambient, 2.0)
                        print(f"DEBUG: plume_data keys = {plume_data.keys() if plume_data else None}")  
                        results['plume_data'] = plume_data
                    elif plume_mode == 2:
                        # Advanced plume
                        print("DEBUG: Calling advanced plume")  
                        plume_data = self.moc_engine.calculate_advanced_plume(p_ambient)
                        results['plume_data'] = plume_data
                    else:
                        # Default
                        plume_data = self.moc_engine.calculate_plume(p_ambient)
                        results['plume_data'] = plume_data
                except Exception as e:
                    print(f"Plume calculation failed: {e}")
            
            # Calculate external flow if enabled
            if params.get('enable_external_flow', False):
                try:
                    exit_mach = results.get('exit_mach', params['mach_exit'])
                    exit_radius = max(results.get('wall_y', [params['throat_height']]))
                    exit_angle = 10.0
                    p_exit = results.get('exit_p_pt', 0.5) * params['p0']
                    p_ambient = params.get('ext_p_ambient', 14.7)
                    num_streamlines = params.get('ext_streamlines', 10)
                    
                    external_data = self.external_flow_calc.calculate_external_expansion(
                        exit_mach, exit_radius, exit_angle, p_exit, p_ambient, num_streamlines
                    )
                    
                    exit_x = max(results.get('wall_x', [0]))
                    for streamline in external_data['streamlines']:
                        streamline['x'] = [exit_x + x for x in streamline['x']]
                    
                    results['external_flow'] = external_data
                    
                    if params.get('show_cowl', False):
                        nozzle_length = max(results.get('wall_x', [0]))
                        cowl_data = self.external_flow_calc.calculate_cowl_design(
                            nozzle_length, exit_radius, exit_angle
                        )
                        results['cowl'] = cowl_data
                    
                    if params.get('calc_afterbody', False):
                        afterbody_data = self.external_flow_calc.calculate_afterbody_pressure(
                            results, p_ambient, afterbody_length=5.0
                        )
                        results['afterbody'] = afterbody_data
                        
                        drag_data = self.external_flow_calc.calculate_drag(
                            results, p_ambient, afterbody_data
                        )
                        results['drag'] = drag_data
                
                except Exception as e:
                    print(f"External flow failed: {e}")
            
            # Expansion fan data
            expansion_fan = self.moc_engine.get_expansion_fan_data()
            if expansion_fan:
                results['expansion_fan_data'] = expansion_fan
            
            # Coalescence data 
            if hasattr(self.moc_engine, 'coalescence_points') and self.moc_engine.coalescence_points:
                coal_data = {
                    'total_count': len(self.moc_engine.coalescence_points),
                    'plus_count': sum(1 for c in self.moc_engine.coalescence_points if c.get('type') == 'C+'),
                    'minus_count': sum(1 for c in self.moc_engine.coalescence_points if c.get('type') == 'C-'),
                    'points': self.moc_engine.coalescence_points
                }
                results['coalescence_data'] = coal_data
            
            self.current_results = results

            # Viscous correction
            if params.get('enable_viscous', False):
                try:
                    from core.viscous import ViscousCorrection
                    vc = ViscousCorrection(
                        gamma=params.get('gamma', 1.4),
                        T0_R=params.get('T0', 3000.0),
                        p0_psia=params.get('p0', 50.0),
                        axisymmetric=params.get('axisym_bl', True),
                        Re_throat=float(params.get('re_throat', 1e6))
                    )
                    wall_x = results.get('wall_x', [])
                    wall_y = results.get('wall_y', [])
                    mach_dist = results.get('mach_distribution', None)
                    if len(wall_x) > 2 and len(wall_y) > 2:
                        corr_y, delta_star, corr_pct = vc.apply_correction(wall_x, wall_y, mach_dist)
                        summary = vc.get_summary(wall_y, delta_star)
                        results['wall_y_inviscid'] = list(wall_y)
                        results['wall_y'] = list(corr_y)
                        results['viscous_correction'] = {
                            'delta_star': list(delta_star),
                            'correction_pct': list(corr_pct),
                            **summary
                        }
                        self.current_results = results
                except Exception as ve:
                    print(f"Viscous correction failed: {ve}")

            # Calculate performance - CORRECT KEY NAMES: p0 and T0
            try:
                perf_calc = PerformanceCalculator(gamma=params['gamma'])
                
                p_total_psf = params['p0'] * 144.0  # FIXED: was params['pto']
                p_ambient_psf = params.get('p_ambient', 14.7) * 144.0
                throat_height = params['throat_height'] / 12.0
                
                if params.get('problem_type', 1) == 1:
                    throat_area = throat_height * 1.0
                    exit_height = results['wall_y'][-1] / 12.0
                    exit_area = exit_height * 1.0
                else:
                    throat_radius = throat_height
                    throat_area = np.pi * throat_radius**2
                    exit_radius = results['wall_y'][-1] / 12.0
                    exit_area = np.pi * exit_radius**2
                
                perf_results = perf_calc.calculate_all_performance(
                    moc_results=results,
                    p_total=p_total_psf,
                    T_total=params['T0'],  # FIXED: was params['tto']
                    p_ambient=p_ambient_psf,
                    throat_area=throat_area,
                    exit_area=exit_area
                )
                
                results['performance'] = perf_results
                
            except Exception as e:
                print(f"Performance calculation failed: {e}")
                import traceback
                traceback.print_exc()
            
            # Display based on view mode
            view_mode = self.input_panels.view_mode_var.get()
            
            if view_mode == DISPLAY_GEOMETRY:
                self.canvas.plot_nozzle_geometry(results, show_characteristics=True)
            elif view_mode in [DISPLAY_MACH, DISPLAY_PRESSURE, DISPLAY_TEMP]:
                X, Y, Z = self.moc_engine.get_contour_data(variable=view_mode)
                self.canvas.plot_contour(X, Y, Z, variable=view_mode)
            
            self.status_bar.config(text=f"Calculation complete - Exit Mach: {results['exit_mach']:.3f}")
            
        except Exception as e:
            messagebox.showerror("Calculation Error", f"An error occurred:\n{str(e)}")
            self.status_bar.config(text="Error in calculation")
            import traceback
            traceback.print_exc()
    def on_given_shape_analysis(self, filepath):
        """Analyze user-provided nozzle shape"""
        try:
            self.status_bar.config(text="Analyzing given shape...")
            self.root.update()
            
            # Read CSV file
            import pandas as pd
            data = pd.read_csv(filepath)
            
            if 'x' not in data.columns or 'y' not in data.columns:
                messagebox.showerror("File Error", "CSV must have 'x' and 'y' columns!")
                return
            
            wall_x = data['x'].values
            wall_y = data['y'].values
            
            # Get parameters
            params = self.input_panels.get_parameters()
            self.moc_engine = MOCEngine(gamma=params['gamma'])
            
            # Analyze given shape
            results = self.moc_engine.calculate_given_shape_analysis(
                wall_x=wall_x,
                wall_y=wall_y,
                mach_exit=params['mach_exit'],
                num_rays=params['num_rays']
            )
            
            self.current_results = results
            
            # Display
            self.canvas.plot_nozzle_geometry(results, show_characteristics=True)
            
            self.status_bar.config(text=f"Given shape analyzed - Exit Mach: {results['exit_mach']:.3f}")
            
            messagebox.showinfo("Analysis Complete", 
                              f"Given shape analyzed successfully!\n\nExit Mach: {results['exit_mach']:.3f}\n\nClick 'Show Results' for details.")
            
        except Exception as e:
            messagebox.showerror("Analysis Error", f"Failed to analyze shape:\n{str(e)}")
            self.status_bar.config(text="Error in analysis")
            import traceback
            traceback.print_exc()
    
