    def show_results_window(self):
        """Show results in popup window"""
        if self.current_results is None:
            messagebox.showinfo("Results", "No results available. Please run calculation first.")
            return
        
        # Create popup window
        results_win = tk.Toplevel(self.root)
        results_win.title("Calculation Results")
        results_win.geometry("600x700")
        
        # Make it stay on top
        results_win.transient(self.root)
        
        # Create scrollable frame
        canvas = tk.Canvas(results_win)
        scrollbar = ttk.Scrollbar(results_win, orient="vertical", command=canvas.yview)
        scrollable_frame = ttk.Frame(canvas)
        
        scrollable_frame.bind(
            "<Configure>",
            lambda e: canvas.configure(scrollregion=canvas.bbox("all"))
        )
        
        canvas.create_window((0, 0), window=scrollable_frame, anchor="nw")
        canvas.configure(yscrollcommand=scrollbar.set)
        
        # Create output panels in popup
        output_panels = OutputPanels(scrollable_frame)
        output_panels.moc_engine_ref = self.moc_engine
        output_panels.update_results(self.current_results)
        
        # Pack canvas and scrollbar
        canvas.pack(side="left", fill="both", expand=True)
        scrollbar.pack(side="right", fill="y")
        
        # Close button at bottom
        close_btn = ttk.Button(results_win, text="Close", command=results_win.destroy)
        close_btn.pack(side="bottom", pady=10)
    
