    def new_project(self):
        response = messagebox.askyesno("New Project", "Clear current results and start new?")
        if response:
            self.input_panels.reset_inputs()
            self.canvas.clear()
            self.current_results = None
            self.status_bar.config(text="Ready")
    def save_project(self):
        """Save project settings to file"""
        try:
            params = self.input_panels.get_parameters()
            
            # Prepare project data
            project_data = {
                'version': '1.0',
                'parameters': {
                    'p0': params['p0'],
                    'T0': params['T0'],
                    'gamma': params['gamma'],
                    'mach_exit': params['mach_exit'],
                    'num_rays': params['num_rays'],
                    'throat_height': params['throat_height'],
                    'problem_type': params['problem_type'],
                    'plume_enabled': params['plume_enabled'],
                    'plume_mode': params['plume_mode'],
                    'p_ambient': params['p_ambient'],
                    'enable_external_flow': params['enable_external_flow'],
                    'use_zone_method': params['use_zone_method']
                }
            }
            
            filename = filedialog.asksaveasfilename(
                defaultextension=".mocproj",
                filetypes=[("MOC Project", "*.mocproj"), ("JSON files", "*.json"), ("All files", "*.*")]
            )
            
            if filename:
                import json
                with open(filename, 'w') as f:
                    json.dump(project_data, f, indent=4)
                
                messagebox.showinfo("Save Complete", f"Project saved to:\n{filename}")
        
        except Exception as e:
            messagebox.showerror("Save Error", f"Failed to save project:\n{str(e)}")
    def load_project(self):
        """Load project settings from file"""
        try:
            filename = filedialog.askopenfilename(
                filetypes=[("MOC Project", "*.mocproj"), ("JSON files", "*.json"), ("All files", "*.*")]
            )
            
            if not filename:
                return
            
            import json
            with open(filename, 'r') as f:
                project_data = json.load(f)
            
            params = project_data.get('parameters', {})
            
            # Load into GUI
            self.input_panels.p0_var.set(str(params.get('p0', 50)))
            self.input_panels.T0_var.set(str(params.get('T0', 3000)))
            self.input_panels.gamma_var.set(str(params.get('gamma', 1.4)))
            self.input_panels.mach_exit_var.set(str(params.get('mach_exit', 2.5)))
            self.input_panels.num_rays_var.set(str(params.get('num_rays', 30)))
            self.input_panels.throat_var.set(str(params.get('throat_height', 1.0)))
            self.input_panels.problem_var.set(params.get('problem_type', 1))
            self.input_panels.plume_var.set(params.get('plume_enabled', 0))
            self.input_panels.plume_mode_var.set(params.get('plume_mode', 1))
            self.input_panels.p_ambient_var.set(str(params.get('p_ambient', 14.7)))
            self.input_panels.external_flow_var.set(params.get('enable_external_flow', 0))
            self.input_panels.zone_method_var.set(params.get('use_zone_method', 0))
            
            messagebox.showinfo("Load Complete", f"Project loaded from:\n{filename}")
            
        except Exception as e:
            messagebox.showerror("Load Error", f"Failed to load project:\n{str(e)}")
