    def export_results(self):
        """Export calculation results to CSV"""
        if self.current_results is None:
            messagebox.showwarning("Export", "No results to export. Calculate first!")
            return
        
        filename = filedialog.asksaveasfilename(
            defaultextension=".csv",
            filetypes=[("CSV files", "*.csv"), ("Excel files", "*.xlsx"), ("All files", "*.*")]
        )
        
        if not filename:
            return
        
        try:
            import pandas as pd
            
            # Geometry data
            geo_data = {
                'x': self.current_results['wall_x'],
                'y': self.current_results['wall_y']
            }
            
            # Flow properties
            if 'mc_mach' in self.current_results:
                n = len(self.current_results['wall_x'])
                geo_data['Mach'] = self.current_results['mc_mach'][:n, 0] if hasattr(self.current_results['mc_mach'], 'shape') else [0] * n
                geo_data['Pressure_Ratio'] = self.current_results['mc_p_pt'][:n, 0] if hasattr(self.current_results['mc_p_pt'], 'shape') else [0] * n
                geo_data['Temp_Ratio'] = self.current_results['mc_T_Tt'][:n, 0] if hasattr(self.current_results['mc_T_Tt'], 'shape') else [0] * n
            
            df = pd.DataFrame(geo_data)
            
            # Export
            if filename.endswith('.xlsx'):
                with pd.ExcelWriter(filename, engine='openpyxl') as writer:
                    df.to_excel(writer, sheet_name='Geometry', index=False)
                    
                    # Performance summary
                    if 'performance' in self.current_results:
                        perf = self.current_results['performance']
                        perf_df = pd.DataFrame([{
                            'Thrust_lbf': perf.get('thrust', 0),
                            'Mass_Flow_lbm_s': perf.get('mass_flow', 0),
                            'Isp_sec': perf.get('Isp', 0),
                            'Efficiency_%': perf.get('efficiency', 0)
                        }])
                        perf_df.to_excel(writer, sheet_name='Performance', index=False)
            else:
                df.to_csv(filename, index=False)
            
            messagebox.showinfo("Export Complete", f"Results exported to:\n{filename}")
            
        except Exception as e:
            messagebox.showerror("Export Error", f"Failed to export:\n{str(e)}")
            import traceback
            traceback.print_exc()
