    def run_batch_processing(self, mach_start_var, mach_end_var, mach_steps_var, 
                            status_text, progress_var, batch_win):
        """Execute batch processing"""
        try:
            # Parse inputs
            mach_start = float(mach_start_var.get())
            mach_end = float(mach_end_var.get())
            steps = int(mach_steps_var.get())
            
            if steps < 2:
                messagebox.showerror("Error", "Steps must be at least 2!")
                return
            
            # Generate Mach values
            mach_values = np.linspace(mach_start, mach_end, steps)
            
            # Get current parameters
            params = self.input_panels.get_parameters()
            
            # Results storage
            batch_results = []
            
            # Update status
            status_text.config(state='normal')
            status_text.delete(1.0, tk.END)
            status_text.insert(tk.END, f"Starting batch processing...\n")
            status_text.insert(tk.END, f"Mach range: {mach_start} to {mach_end} ({steps} steps)\n")
            status_text.insert(tk.END, "=" * 50 + "\n\n")
            status_text.config(state='disabled')
            batch_win.update()
            
            # Run calculations
            for i, mach in enumerate(mach_values):
                status_text.config(state='normal')
                status_text.insert(tk.END, f"Case {i+1}/{steps}: Mach = {mach:.2f}... ")
                status_text.config(state='disabled')
                batch_win.update()
                
                # Update params
                params['mach_exit'] = mach
                
                # Calculate
                self.moc_engine = MOCEngine(gamma=params['gamma'])
                
                if params['problem_type'] == 1:
                    results = self.moc_engine.calculate_2d_ideal_nozzle(
                        mach_exit=mach,
                        num_rays=params['num_rays'],
                        throat_height=params['throat_height']
                    )
                elif params['problem_type'] == 2:
                    results = self.moc_engine.calculate_axisymmetric_nozzle(
                        mach_exit=mach,
                        num_rays=params['num_rays'],
                        throat_radius=params['throat_height']
                    )
                else:
                    messagebox.showwarning("Batch", "Only types 1 and 2 supported in batch mode!")
                    return
                
                # Store results
                batch_results.append({
                    'mach_exit': mach,
                    'exit_height': results['wall_y'][-1],
                    'nozzle_length': results['wall_x'][-1],
                    'area_ratio': results['wall_y'][-1] / params['throat_height']
                })
                
                # Update progress
                progress_var.set((i + 1) / steps * 100)
                
                status_text.config(state='normal')
                status_text.insert(tk.END, f"Done! Area ratio = {batch_results[-1]['area_ratio']:.3f}\n")
                status_text.config(state='disabled')
                batch_win.update()
            
            # Summary
            status_text.config(state='normal')
            status_text.insert(tk.END, "\n" + "=" * 50 + "\n")
            status_text.insert(tk.END, f"Batch processing complete! {len(batch_results)} cases run.\n\n")
            status_text.insert(tk.END, "SUMMARY:\n")
            for res in batch_results:
                status_text.insert(tk.END, f"  M={res['mach_exit']:.2f}: A/A*={res['area_ratio']:.3f}, L={res['nozzle_length']:.3f}\n")
            status_text.config(state='disabled')
            
            # Offer export
            if messagebox.askyesno("Batch Complete", "Batch processing complete!\n\nExport results to CSV?"):
                self.export_batch_results(batch_results)
            
        except Exception as e:
            messagebox.showerror("Batch Error", f"Error in batch processing:\n{str(e)}")
            import traceback
            traceback.print_exc()
    
