    def run_design_comparison(self, mach_a_var, rays_a_var, type_a_var, result_a_text,
                              mach_b_var, rays_b_var, type_b_var, result_b_text,
                              summary_text, comp_win):
        """Execute design comparison"""
        try:
            params = self.input_panels.get_parameters()
            
            # Design A
            result_a_text.config(state='normal')
            result_a_text.delete(1.0, tk.END)
            result_a_text.insert(tk.END, "Calculating Design A...\n")
            result_a_text.config(state='disabled')
            comp_win.update()
            
            mach_a = float(mach_a_var.get())
            rays_a = int(rays_a_var.get())
            type_a = type_a_var.get()
            
            engine_a = MOCEngine(gamma=params['gamma'])
            results_a = self._calculate_design(engine_a, mach_a, rays_a, type_a, params)
            
            result_a_text.config(state='normal')
            result_a_text.delete(1.0, tk.END)
            result_a_text.insert(tk.END, f"DESIGN A RESULTS:\n{'='*40}\n")
            result_a_text.insert(tk.END, f"Exit Mach: {results_a['exit_mach']:.4f}\n")
            result_a_text.insert(tk.END, f"Exit Height: {results_a['wall_y'][-1]:.4f} in\n")
            result_a_text.insert(tk.END, f"Length: {results_a['wall_x'][-1]:.4f} in\n")
            result_a_text.insert(tk.END, f"Area Ratio: {results_a['wall_y'][-1]/params['throat_height']:.4f}\n")
            if 'shocks' in results_a:
                result_a_text.insert(tk.END, f"\nShocks: {len(results_a['shocks'])}\n")
            result_a_text.config(state='disabled')
            
            # Design B
            result_b_text.config(state='normal')
            result_b_text.delete(1.0, tk.END)
            result_b_text.insert(tk.END, "Calculating Design B...\n")
            result_b_text.config(state='disabled')
            comp_win.update()
            
            mach_b = float(mach_b_var.get())
            rays_b = int(rays_b_var.get())
            type_b = type_b_var.get()
            
            engine_b = MOCEngine(gamma=params['gamma'])
            results_b = self._calculate_design(engine_b, mach_b, rays_b, type_b, params)
            
            result_b_text.config(state='normal')
            result_b_text.delete(1.0, tk.END)
            result_b_text.insert(tk.END, f"DESIGN B RESULTS:\n{'='*40}\n")
            result_b_text.insert(tk.END, f"Exit Mach: {results_b['exit_mach']:.4f}\n")
            result_b_text.insert(tk.END, f"Exit Height: {results_b['wall_y'][-1]:.4f} in\n")
            result_b_text.insert(tk.END, f"Length: {results_b['wall_x'][-1]:.4f} in\n")
            result_b_text.insert(tk.END, f"Area Ratio: {results_b['wall_y'][-1]/params['throat_height']:.4f}\n")
            if 'shocks' in results_b:
                result_b_text.insert(tk.END, f"\nShocks: {len(results_b['shocks'])}\n")
            result_b_text.config(state='disabled')
            
            # Summary
            summary_text.config(state='normal')
            summary_text.delete(1.0, tk.END)
            summary_text.insert(tk.END, "COMPARISON SUMMARY:\n" + "="*100 + "\n\n")
            
            length_diff = ((results_b['wall_x'][-1] - results_a['wall_x'][-1]) / results_a['wall_x'][-1]) * 100
            area_diff = ((results_b['wall_y'][-1] - results_a['wall_y'][-1]) / results_a['wall_y'][-1]) * 100
            
            summary_text.insert(tk.END, f"Length Difference: {length_diff:+.2f}%\n")
            summary_text.insert(tk.END, f"Area Difference: {area_diff:+.2f}%\n\n")
            summary_text.insert(tk.END, "RECOMMENDATIONS:\n")
            
            if abs(length_diff) < 5:
                summary_text.insert(tk.END, "  • Similar lengths\n")
            elif length_diff < 0:
                summary_text.insert(tk.END, f"  • Design A is {abs(length_diff):.1f}% shorter\n")
            else:
                summary_text.insert(tk.END, f"  • Design B is {abs(length_diff):.1f}% shorter\n")
            
            summary_text.config(state='disabled')
            
        except Exception as e:
            messagebox.showerror("Comparison Error", f"Failed:\n{str(e)}")
            import traceback
            traceback.print_exc()
    
    def _calculate_design(self, engine, mach, rays, prob_type, params):
        """Helper to calculate single design"""
        if prob_type == 1:
            return engine.calculate_2d_ideal_nozzle(mach, rays, params['throat_height'])
        elif prob_type == 2:
            return engine.calculate_axisymmetric_nozzle(mach, rays, params['throat_height'])
        elif prob_type == 3:
            return engine.calculate_plug_nozzle(mach, rays, params['throat_height'], 0.8)
        elif prob_type == 4:
            return engine.calculate_cone_nozzle(mach, rays, params['throat_height'], 15.0)
        elif prob_type == 5:
            return engine.calculate_wedge_nozzle(mach, rays, params['throat_height'], 12.0)
        elif prob_type == 6:
            return engine.calculate_bell_nozzle(mach, rays, params['throat_height'], 0.8, 0.8)
        elif prob_type == 7:
            return engine.calculate_truncated_ideal_nozzle(mach, rays, params['throat_height'], 0.75)
        elif prob_type == 8:
            return engine.calculate_minimum_length_nozzle(mach, rays, params['throat_height'])
        elif prob_type == 9:
            return engine.calculate_throat_expansion_nozzle(mach, rays, params['throat_height'], 45.0)
    
    def show_pressure_distribution(self):
        """Show pressure distribution plot"""
        if self.current_results is None or self.moc_engine is None:
            messagebox.showinfo("Pressure Plot", "Calculate first!")
            return
        
        press_win = tk.Toplevel(self.root)
        press_win.title("Pressure Distribution")
        press_win.geometry("900x700")
        
        from matplotlib.figure import Figure
        from matplotlib.backends.backend_tkagg import FigureCanvasTkAgg
        
        fig = Figure(figsize=(9, 7))
        ax1 = fig.add_subplot(2, 1, 1)
        
        wall_x = self.current_results['wall_x']
        
        if hasattr(self.moc_engine, 'mc_p_pt'):
            n = len(wall_x)
            if self.moc_engine.mc_p_pt.ndim == 2:
                wall_pressure = self.moc_engine.mc_p_pt[:n, 0]
            else:
                wall_pressure = [self.moc_engine.mc_p_pt[i] if i < len(self.moc_engine.mc_p_pt) else 0 for i in range(n)]
        else:
            wall_pressure = [0.5] * len(wall_x)
        
        ax1.plot(wall_x, wall_pressure, 'b-', linewidth=2, label='Wall Pressure')
        ax1.axhline(y=self.current_results.get('exit_p_pt', 0.5), color='r', 
                   linestyle='--', label='Exit Pressure')
        ax1.set_xlabel('Axial Position (in)', fontsize=10)
        ax1.set_ylabel('Pressure Ratio (p/p_t)', fontsize=10)
        ax1.set_title('Pressure Distribution Along Wall', fontsize=12, fontweight='bold')
        ax1.grid(True, alpha=0.3)
        ax1.legend()
        
        ax2 = fig.add_subplot(2, 1, 2)
        pressure_gradient = np.gradient(wall_pressure, wall_x)
        
        ax2.plot(wall_x, pressure_gradient, 'g-', linewidth=2)
        ax2.axhline(y=0, color='k', linestyle='-', linewidth=0.5)
        ax2.set_xlabel('Axial Position (in)', fontsize=10)
        ax2.set_ylabel('Pressure Gradient (dp/dx)', fontsize=10)
        ax2.set_title('Pressure Gradient', fontsize=12, fontweight='bold')
        ax2.grid(True, alpha=0.3)
        
        fig.text(0.15, 0.95, 
                f"Max: {max(wall_pressure):.4f} | Min: {min(wall_pressure):.4f} | Exit: {self.current_results.get('exit_p_pt', 0):.4f}",
                fontsize=9, bbox=dict(boxstyle='round', facecolor='wheat', alpha=0.8))
        
        fig.tight_layout()
        
        canvas = FigureCanvasTkAgg(fig, master=press_win)
        canvas.draw()
        canvas.get_tk_widget().pack(fill=tk.BOTH, expand=True)
        
        def export_data():
            filename = filedialog.asksaveasfilename(defaultextension=".csv", filetypes=[("CSV", "*.csv")])
            if filename:
                import pandas as pd
                df = pd.DataFrame({'x': wall_x, 'pressure': wall_pressure, 'gradient': pressure_gradient})
                df.to_csv(filename, index=False)
                messagebox.showinfo("Export", f"Exported to:\n{filename}")
        
        ttk.Button(press_win, text="Export Data", command=export_data).pack(pady=10)
    def show_velocity_vectors(self):
        """Show velocity vector field"""
        if self.current_results is None or self.moc_engine is None:
            messagebox.showinfo("Velocity Vectors", "Calculate first!")
            return
        
        vec_win = tk.Toplevel(self.root)
        vec_win.title("Velocity Vector Field")
        vec_win.geometry("1000x800")
        
        from matplotlib.figure import Figure
        from matplotlib.backends.backend_tkagg import FigureCanvasTkAgg
        
        fig = Figure(figsize=(10, 8))
        ax = fig.add_subplot(111)
        
        # Get grid data
        try:
            X, Y, Z_mach = self.moc_engine.get_contour_data(variable='mach')
            
            # Calculate velocity components
            # V_x = Mach * cos(theta), V_y = Mach * sin(theta)
            if hasattr(self.moc_engine, 'mc_turn'):
                theta = self.moc_engine.mc_turn
                if theta.ndim == 2:
                    theta_grid = theta[:X.shape[0], :X.shape[1]]
                else:
                    theta_grid = np.zeros_like(X)
            else:
                theta_grid = np.zeros_like(X)
            
            # Velocity components
            U = Z_mach * np.cos(theta_grid)  # x-component
            V = Z_mach * np.sin(theta_grid)  # y-component
            
            # Plot contour as background
            contour = ax.contourf(X, Y, Z_mach, levels=20, cmap='jet', alpha=0.6)
            fig.colorbar(contour, ax=ax, label='Mach Number')
            
            # Plot velocity vectors (subsample for clarity)
            step = max(1, X.shape[0] // 20)
            ax.quiver(X[::step, ::step], Y[::step, ::step], 
                     U[::step, ::step], V[::step, ::step],
                     scale=50, width=0.003, color='white', alpha=0.8)
            
            # Plot nozzle geometry
            wall_x = self.current_results['wall_x']
            wall_y = self.current_results['wall_y']
            ax.plot(wall_x, wall_y, 'k-', linewidth=2, label='Upper Wall')
            ax.plot(wall_x, [-y for y in wall_y], 'k-', linewidth=2, label='Lower Wall')
            
            ax.set_xlabel('Axial Position (in)', fontsize=11)
            ax.set_ylabel('Radial Position (in)', fontsize=11)
            ax.set_title('Velocity Vector Field', fontsize=13, fontweight='bold')
            ax.grid(True, alpha=0.3)
            ax.legend()
            ax.set_aspect('equal')
            
            canvas = FigureCanvasTkAgg(fig, master=vec_win)
            canvas.draw()
            canvas.get_tk_widget().pack(fill=tk.BOTH, expand=True)
            
        except Exception as e:
            messagebox.showerror("Velocity Error", f"Failed to generate vectors:\n{str(e)}")
            import traceback
            traceback.print_exc()
    def show_offdesign_analysis(self):
        """Show off-design performance analysis"""
        if self.current_results is None:
            messagebox.showinfo("Off-Design", "Calculate first!")
            return
        
        offdesign_win = tk.Toplevel(self.root)
        offdesign_win.title("Off-Design Performance Analysis")
        offdesign_win.geometry("900x700")
        
        from matplotlib.figure import Figure
        from matplotlib.backends.backend_tkagg import FigureCanvasTkAgg
        
        # Ambient pressure range (sea level to high altitude)
        p_amb_range = np.linspace(2.0, 14.7, 30)  # psia
        
        # Calculate thrust for each ambient pressure
        thrust_values = []
        efficiency_values = []
        
        params = self.input_panels.get_parameters()
        
        for p_amb in p_amb_range:
            # Simplified thrust calculation
            p_exit = self.current_results.get('exit_p_pt', 0.5) * params['p0']
            
            # Thrust coefficient
            if params.get('problem_type', 1) == 1:
                exit_area = self.current_results['wall_y'][-1] * 1.0 / 144.0  # ft^2
            else:
                exit_area = np.pi * (self.current_results['wall_y'][-1] / 12.0)**2
            
            thrust = exit_area * ((p_exit - p_amb) * 144.0)  # lbf
            
            # Efficiency (simple model)
            pressure_ratio = p_amb / p_exit if p_exit > 0 else 1.0
            if pressure_ratio < 0.8:
                efficiency = 85 + (1.0 - pressure_ratio) * 10  # Under-expanded
            elif pressure_ratio > 1.2:
                efficiency = 85 - (pressure_ratio - 1.0) * 20  # Over-expanded
            else:
                efficiency = 95  # Near optimal
            
            thrust_values.append(thrust)
            efficiency_values.append(max(0, min(100, efficiency)))
        
        # Create plots
        fig = Figure(figsize=(9, 7))
        
        # Thrust vs altitude
        ax1 = fig.add_subplot(2, 1, 1)
        ax1.plot(p_amb_range, thrust_values, 'b-', linewidth=2)
        ax1.axvline(x=14.7, color='g', linestyle='--', label='Sea Level')
        ax1.axvline(x=10.1, color='orange', linestyle='--', label='10k ft')
        ax1.axvline(x=4.4, color='r', linestyle='--', label='30k ft')
        ax1.set_xlabel('Ambient Pressure (psia)', fontsize=10)
        ax1.set_ylabel('Thrust (lbf)', fontsize=10)
        ax1.set_title('Thrust vs Ambient Pressure (Altitude)', fontsize=12, fontweight='bold')
        ax1.grid(True, alpha=0.3)
        ax1.legend()
        
        # Efficiency
        ax2 = fig.add_subplot(2, 1, 2)
        ax2.plot(p_amb_range, efficiency_values, 'r-', linewidth=2)
        ax2.axhline(y=90, color='g', linestyle='--', alpha=0.5, label='Target 90%')
        ax2.set_xlabel('Ambient Pressure (psia)', fontsize=10)
        ax2.set_ylabel('Efficiency (%)', fontsize=10)
        ax2.set_title('Nozzle Efficiency vs Altitude', fontsize=12, fontweight='bold')
        ax2.grid(True, alpha=0.3)
        ax2.legend()
        ax2.set_ylim([0, 105])
        
        fig.tight_layout()
        
        canvas = FigureCanvasTkAgg(fig, master=offdesign_win)
        canvas.draw()
        canvas.get_tk_widget().pack(fill=tk.BOTH, expand=True)
    def show_altitude_curves(self):
        """Show altitude performance curves"""
        if self.current_results is None:
            messagebox.showinfo("Altitude Performance", "Calculate first!")
            return
        
        alt_win = tk.Toplevel(self.root)
        alt_win.title("Altitude Performance Curves")
        alt_win.geometry("1000x800")
        
        from matplotlib.figure import Figure
        from matplotlib.backends.backend_tkagg import FigureCanvasTkAgg
        
        # Altitude range (0 to 50,000 ft)
        altitudes = np.linspace(0, 50000, 50)
        
        # Calculate atmospheric properties and performance
        thrust_vals = []
        isp_vals = []
        pressure_vals = []
        temp_vals = []
        
        params = self.input_panels.get_parameters()
        
        for alt in altitudes:
            # Standard atmosphere model
            if alt <= 36089:  # Troposphere
                T = 518.67 - 0.00356616 * alt  # Rankine
                p = 14.696 * (T / 518.67)**5.2561  # psia
            else:  # Stratosphere
                T = 389.97
                p = 14.696 * 0.2234 * np.exp((36089 - alt) / 20806)
            
            pressure_vals.append(p)
            temp_vals.append(T)
            
            # Performance calculations
            p_exit = self.current_results.get('exit_p_pt', 0.5) * params['p0']
            
            if params.get('problem_type', 1) == 1:
                exit_area = self.current_results['wall_y'][-1] * 1.0 / 144.0
            else:
                exit_area = np.pi * (self.current_results['wall_y'][-1] / 12.0)**2
            
            # Thrust
            thrust = exit_area * ((p_exit - p) * 144.0)
            thrust_vals.append(max(0, thrust))
            
            # Isp (GERÇEK HESAPLAMA!)
            throat_area = params['throat_height'] / 12.0  # ft
            if params.get('problem_type', 1) == 1:
                throat_area_sq = throat_area * 1.0 / 144.0
            else:
                throat_area_sq = np.pi * (throat_area)**2
            
            # Mass flow from isentropic flow
            gamma = params['gamma']
            R = 1716.0  # ft-lbf/(slug-R) for air
            T_total = params['T0']  # Rankine
            p_total = params['p0'] * 144.0  # psf
            
            mass_flow = (p_total * throat_area_sq / np.sqrt(T_total)) * \
                       np.sqrt(gamma / R) * \
                       ((gamma + 1) / 2)**((gamma + 1) / (2 * (gamma - 1)))
            
            isp = thrust / (mass_flow * 32.174) if mass_flow > 0 else 0
            isp_vals.append(isp)
        
        # Create 4 subplots
        fig = Figure(figsize=(10, 8))
        
        # Thrust vs Altitude
        ax1 = fig.add_subplot(2, 2, 1)
        ax1.plot(altitudes/1000, thrust_vals, 'b-', linewidth=2)
        ax1.set_xlabel('Altitude (1000 ft)', fontsize=9)
        ax1.set_ylabel('Thrust (lbf)', fontsize=9)
        ax1.set_title('Thrust vs Altitude', fontsize=10, fontweight='bold')
        ax1.grid(True, alpha=0.3)
        
        # Isp vs Altitude
        ax2 = fig.add_subplot(2, 2, 2)
        ax2.plot(altitudes/1000, isp_vals, 'r-', linewidth=2)
        ax2.set_xlabel('Altitude (1000 ft)', fontsize=9)
        ax2.set_ylabel('Isp (sec)', fontsize=9)
        ax2.set_title('Specific Impulse vs Altitude', fontsize=10, fontweight='bold')
        ax2.grid(True, alpha=0.3)
        
        # Ambient Pressure
        ax3 = fig.add_subplot(2, 2, 3)
        ax3.plot(altitudes/1000, pressure_vals, 'g-', linewidth=2)
        ax3.set_xlabel('Altitude (1000 ft)', fontsize=9)
        ax3.set_ylabel('Pressure (psia)', fontsize=9)
        ax3.set_title('Ambient Pressure vs Altitude', fontsize=10, fontweight='bold')
        ax3.grid(True, alpha=0.3)
        
        # Temperature
        ax4 = fig.add_subplot(2, 2, 4)
        ax4.plot(altitudes/1000, temp_vals, 'orange', linewidth=2)
        ax4.set_xlabel('Altitude (1000 ft)', fontsize=9)
        ax4.set_ylabel('Temperature (°R)', fontsize=9)
        ax4.set_title('Ambient Temperature vs Altitude', fontsize=10, fontweight='bold')
        ax4.grid(True, alpha=0.3)
        
        fig.tight_layout()
        
        canvas = FigureCanvasTkAgg(fig, master=alt_win)
        canvas.draw()
        canvas.get_tk_widget().pack(fill=tk.BOTH, expand=True)
