    def show_multiple_viewports(self):
        """Show multiple viewports in 2x2 grid"""
        if self.current_results is None or self.moc_engine is None:
            messagebox.showinfo("Multiple Viewports", "Calculate first!")
            return
        
        viewport_win = tk.Toplevel(self.root)
        viewport_win.title("Multiple Viewports - 2x2 Layout")
        viewport_win.geometry("1400x1000")
        
        from matplotlib.figure import Figure
        from matplotlib.backends.backend_tkagg import FigureCanvasTkAgg
        
        # Create 2x2 subplot
        fig = Figure(figsize=(14, 10))
        
        try:
            # VIEWPORT 1: Nozzle Geometry with Characteristics
            ax1 = fig.add_subplot(2, 2, 1)
            
            wall_x = self.current_results['wall_x']
            wall_y = self.current_results['wall_y']
            
            ax1.plot(wall_x, wall_y, 'k-', linewidth=2, label='Upper Wall')
            ax1.plot(wall_x, [-y for y in wall_y], 'k-', linewidth=2, label='Lower Wall')
            
            # Add characteristics if available
            if hasattr(self.moc_engine, 'mc_x') and hasattr(self.moc_engine, 'mc_y'):
                mc_x = self.moc_engine.mc_x
                mc_y = self.moc_engine.mc_y
                
                # Draw some characteristic lines
                for i in range(0, mc_x.shape[0], max(1, mc_x.shape[0]//10)):
                    for j in range(0, mc_x.shape[1], max(1, mc_x.shape[1]//10)):
                        if not np.isnan(mc_x[i,j]) and not np.isnan(mc_y[i,j]):
                            ax1.plot(mc_x[i,j], mc_y[i,j], 'b.', markersize=2, alpha=0.3)
            
            ax1.set_xlabel('Axial Position (in)', fontsize=9)
            ax1.set_ylabel('Radial Position (in)', fontsize=9)
            ax1.set_title('Nozzle Geometry + Characteristics', fontsize=10, fontweight='bold')
            ax1.grid(True, alpha=0.3)
            ax1.set_aspect('equal')
            ax1.legend(fontsize=8)
            
            # VIEWPORT 2: Mach Number Contour
            ax2 = fig.add_subplot(2, 2, 2)
            
            X, Y, Z_mach = self.moc_engine.get_contour_data(variable='mach')
            contour2 = ax2.contourf(X, Y, Z_mach, levels=20, cmap='jet')
            fig.colorbar(contour2, ax=ax2, label='Mach Number')
            
            ax2.plot(wall_x, wall_y, 'k-', linewidth=2)
            ax2.plot(wall_x, [-y for y in wall_y], 'k-', linewidth=2)
            
            ax2.set_xlabel('Axial Position (in)', fontsize=9)
            ax2.set_ylabel('Radial Position (in)', fontsize=9)
            ax2.set_title('Mach Number Distribution', fontsize=10, fontweight='bold')
            ax2.set_aspect('equal')
            
            # VIEWPORT 3: Pressure Distribution
            ax3 = fig.add_subplot(2, 2, 3)
            
            X_p, Y_p, Z_pressure = self.moc_engine.get_contour_data(variable='pressure')
            contour3 = ax3.contourf(X_p, Y_p, Z_pressure, levels=20, cmap='viridis')
            fig.colorbar(contour3, ax=ax3, label='Pressure Ratio (p/pt)')
            
            ax3.plot(wall_x, wall_y, 'k-', linewidth=2)
            ax3.plot(wall_x, [-y for y in wall_y], 'k-', linewidth=2)
            
            ax3.set_xlabel('Axial Position (in)', fontsize=9)
            ax3.set_ylabel('Radial Position (in)', fontsize=9)
            ax3.set_title('Pressure Distribution', fontsize=10, fontweight='bold')
            ax3.set_aspect('equal')
            
            # VIEWPORT 4: Temperature Distribution
            ax4 = fig.add_subplot(2, 2, 4)
            
            X_t, Y_t, Z_temp = self.moc_engine.get_contour_data(variable='temperature')
            contour4 = ax4.contourf(X_t, Y_t, Z_temp, levels=20, cmap='hot')
            fig.colorbar(contour4, ax=ax4, label='Temperature Ratio (T/Tt)')
            
            ax4.plot(wall_x, wall_y, 'k-', linewidth=2)
            ax4.plot(wall_x, [-y for y in wall_y], 'k-', linewidth=2)
            
            ax4.set_xlabel('Axial Position (in)', fontsize=9)
            ax4.set_ylabel('Radial Position (in)', fontsize=9)
            ax4.set_title('Temperature Distribution', fontsize=10, fontweight='bold')
            ax4.set_aspect('equal')
            
            fig.tight_layout()
            
            canvas = FigureCanvasTkAgg(fig, master=viewport_win)
            canvas.draw()
            canvas.get_tk_widget().pack(fill=tk.BOTH, expand=True)
            
            # Add info text
            info_text = f"Exit Mach: {self.current_results['exit_mach']:.3f} | " \
                       f"Length: {wall_x[-1]:.2f} in | " \
                       f"Area Ratio: {wall_y[-1]/self.input_panels.get_parameters()['throat_height']:.2f}"
            
            info_label = ttk.Label(viewport_win, text=info_text, font=('Arial', 10, 'bold'))
            info_label.pack(pady=5)
            
        except Exception as e:
            messagebox.showerror("Viewport Error", f"Failed to create viewports:\n{str(e)}")
            import traceback
            traceback.print_exc()
    def show_temperature_analysis(self):
        """Show advanced temperature analysis"""
        if self.current_results is None or self.moc_engine is None:
            messagebox.showinfo("Temperature Analysis", "Calculate first!")
            return
        
        temp_win = tk.Toplevel(self.root)
        temp_win.title("Advanced Temperature Analysis")
        temp_win.geometry("1200x900")
        
        from matplotlib.figure import Figure
        from matplotlib.backends.backend_tkagg import FigureCanvasTkAgg
        
        fig = Figure(figsize=(12, 9))
        
        try:
            X, Y, Z_temp = self.moc_engine.get_contour_data(variable='temperature')
            
            wall_x = self.current_results['wall_x']
            wall_y = self.current_results['wall_y']
            
            params = self.input_panels.get_parameters()
            T_total = params['T0']  # Total temperature in Rankine
            
            # Convert ratio to actual temperature
            T_actual = Z_temp * T_total
            
            # PLOT 1: Temperature Contour with Isotherms
            ax1 = fig.add_subplot(3, 1, 1)
            
            contour_filled = ax1.contourf(X, Y, T_actual, levels=30, cmap='hot')
            fig.colorbar(contour_filled, ax=ax1, label='Temperature (°R)')
            
            # Add isothermal lines
            contour_lines = ax1.contour(X, Y, T_actual, levels=15, colors='white', 
                                       linewidths=0.5, alpha=0.6)
            ax1.clabel(contour_lines, inline=True, fontsize=7, fmt='%.0f°R')
            
            ax1.plot(wall_x, wall_y, 'k-', linewidth=2)
            ax1.plot(wall_x, [-y for y in wall_y], 'k-', linewidth=2)
            
            ax1.set_xlabel('Axial Position (in)', fontsize=10)
            ax1.set_ylabel('Radial Position (in)', fontsize=10)
            ax1.set_title('Temperature Distribution with Isothermal Lines', 
                         fontsize=11, fontweight='bold')
            ax1.set_aspect('equal')
            
            # PLOT 2: Temperature Gradient Magnitude
            ax2 = fig.add_subplot(3, 1, 2)
            
            # Calculate gradient
            grad_x = np.gradient(T_actual, axis=1)
            grad_y = np.gradient(T_actual, axis=0)
            grad_magnitude = np.sqrt(grad_x**2 + grad_y**2)
            
            contour_grad = ax2.contourf(X, Y, grad_magnitude, levels=20, cmap='plasma')
            fig.colorbar(contour_grad, ax=ax2, label='Temperature Gradient (°R/in)')
            
            ax2.plot(wall_x, wall_y, 'k-', linewidth=2)
            ax2.plot(wall_x, [-y for y in wall_y], 'k-', linewidth=2)
            
            # Mark high gradient regions
            threshold = np.percentile(grad_magnitude, 90)
            high_grad = grad_magnitude > threshold
            ax2.contour(X, Y, high_grad, levels=[0.5], colors='cyan', 
                       linewidths=2, linestyles='--')
            
            ax2.set_xlabel('Axial Position (in)', fontsize=10)
            ax2.set_ylabel('Radial Position (in)', fontsize=10)
            ax2.set_title('Temperature Gradient Magnitude (High gradients in cyan)', 
                         fontsize=11, fontweight='bold')
            ax2.set_aspect('equal')
            
            # PLOT 3: Wall Temperature Distribution
            ax3 = fig.add_subplot(3, 1, 3)
            
            # Get temperature along wall
            if hasattr(self.moc_engine, 'mc_T_Tt'):
                n = len(wall_x)
                if self.moc_engine.mc_T_Tt.ndim == 2:
                    wall_temp_ratio = self.moc_engine.mc_T_Tt[:n, 0]
                else:
                    wall_temp_ratio = np.array([self.moc_engine.mc_T_Tt[i] if i < len(self.moc_engine.mc_T_Tt) else 0.5 for i in range(n)])
                
                wall_temp_actual = wall_temp_ratio * T_total
            else:
                # Fallback
                wall_temp_actual = T_actual[0, :] if T_actual.shape[1] >= len(wall_x) else np.linspace(T_total*0.8, T_total*0.4, len(wall_x))
            
            # Ensure same length
            if len(wall_temp_actual) != len(wall_x):
                wall_temp_actual = np.interp(wall_x, 
                                             np.linspace(wall_x[0], wall_x[-1], len(wall_temp_actual)),
                                             wall_temp_actual)
            
            ax3.plot(wall_x, wall_temp_actual, 'r-', linewidth=2, label='Wall Temperature')
            ax3.axhline(y=T_total, color='b', linestyle='--', label=f'Total Temp ({T_total:.0f}°R)')
            
            # Mark critical points
            min_temp_idx = np.argmin(wall_temp_actual)
            ax3.plot(wall_x[min_temp_idx], wall_temp_actual[min_temp_idx], 'go', 
                    markersize=10, label=f'Min: {wall_temp_actual[min_temp_idx]:.0f}°R')
            
            # Temperature drop
            temp_drop = T_total - wall_temp_actual[-1]
            ax3.annotate(f'ΔT = {temp_drop:.0f}°R\n({(temp_drop/T_total)*100:.1f}%)', 
                        xy=(wall_x[-1], wall_temp_actual[-1]),
                        xytext=(wall_x[-1]*0.7, wall_temp_actual[-1]*1.1),
                        arrowprops=dict(arrowstyle='->', color='black'),
                        fontsize=9, bbox=dict(boxstyle='round', facecolor='yellow', alpha=0.7))
            
            ax3.set_xlabel('Axial Position (in)', fontsize=10)
            ax3.set_ylabel('Temperature (°R)', fontsize=10)
            ax3.set_title('Wall Temperature Distribution', fontsize=11, fontweight='bold')
            ax3.grid(True, alpha=0.3)
            ax3.legend(loc='best', fontsize=9)
            
            # Statistics box
            stats_text = f"TEMPERATURE STATISTICS:\n" \
                        f"Total Temperature: {T_total:.0f}°R ({(T_total-459.67):.0f}°F)\n" \
                        f"Exit Temperature: {wall_temp_actual[-1]:.0f}°R ({(wall_temp_actual[-1]-459.67):.0f}°F)\n" \
                        f"Min Temperature: {np.min(wall_temp_actual):.0f}°R ({(np.min(wall_temp_actual)-459.67):.0f}°F)\n" \
                        f"Temperature Drop: {temp_drop:.0f}°R ({(temp_drop/T_total)*100:.1f}%)\n" \
                        f"Max Gradient: {np.max(grad_magnitude):.1f}°R/in"
            
            fig.text(0.02, 0.02, stats_text, fontsize=8, family='monospace',
                    bbox=dict(boxstyle='round', facecolor='lightblue', alpha=0.8))
            
            fig.tight_layout()
            
            canvas = FigureCanvasTkAgg(fig, master=temp_win)
            canvas.draw()
            canvas.get_tk_widget().pack(fill=tk.BOTH, expand=True)
            
        except Exception as e:
            messagebox.showerror("Temperature Error", f"Failed:\n{str(e)}")
            import traceback
            traceback.print_exc()
