    def show_weight_analysis(self):
        """Weight estimation - core/weight.py"""
        import tkinter as tk
        from tkinter import ttk, messagebox
        from matplotlib.figure import Figure
        from matplotlib.backends.backend_tkagg import FigureCanvasTkAgg
        import numpy as np

        win = tk.Toplevel(self.root)
        win.title("Weight Estimation")
        win.geometry("1200x850")

        ttk.Label(win, text="Nozzle Weight Estimation",
                 font=('Arial', 14, 'bold')).pack(pady=8)

        cfg = ttk.LabelFrame(win, text="Settings", padding=8)
        cfg.pack(fill=tk.X, padx=10, pady=5)

        from core.thermal import MATERIALS
        params = self.input_panels.get_parameters()

        ttk.Label(cfg, text="Material:").grid(row=0, column=0, sticky=tk.W)
        mat_var = tk.StringVar(value="Inconel 718")
        ttk.Combobox(cfg, textvariable=mat_var, values=list(MATERIALS.keys()),
                    width=22, state='readonly').grid(row=0, column=1, padx=5)

        ttk.Label(cfg, text="Wall thickness (mm):").grid(row=0, column=2, sticky=tk.W, padx=10)
        thick_var = tk.StringVar(value="3.0")
        ttk.Entry(cfg, textvariable=thick_var, width=8).grid(row=0, column=3)

        run_btn = ttk.Button(cfg, text="▶ Calculate Weight", style='Accent.TButton')
        run_btn.grid(row=0, column=4, padx=20)

        fig = Figure(figsize=(12, 6))
        canvas_widget = FigureCanvasTkAgg(fig, master=win)
        canvas_widget.get_tk_widget().pack(fill=tk.BOTH, expand=True, padx=10, pady=5)

        def run_analysis():
            if not self.current_results:
                messagebox.showwarning("No Data", "Run a nozzle calculation first.")
                return
            try:
                from core.weight import WeightEstimation
                results = self.current_results
                wall_x = results.get('wall_x', [])
                wall_y = results.get('wall_y', [])
                if len(wall_x) < 3:
                    return

                we = WeightEstimation(mat_var.get(), float(thick_var.get()))
                mass_result = we.nozzle_mass(wall_x, wall_y)
                breakdown   = we.mass_breakdown(wall_x, wall_y)
                mat_compare = we.compare_materials(wall_x, wall_y)

                thrust_lbf = results.get('performance', {}).get('thrust', 0)
                thrust_N   = thrust_lbf * 4.44822
                tw = we.thrust_to_weight(mass_result['mass_kg'], thrust_N)

                fig.clear()

                ax1 = fig.add_subplot(1, 3, 1)
                sections = [k for k in breakdown if k != 'Total']
                masses   = [breakdown[k] for k in sections]
                colors   = ['#3498DB', '#E74C3C', '#2ECC71']
                ax1.pie(masses, labels=sections, colors=colors,
                       autopct='%1.1f%%', startangle=90)
                ax1.set_title('Mass by Section', fontweight='bold')

                ax2 = fig.add_subplot(1, 3, 2)
                mat_names = list(mat_compare.keys())
                mat_masses = [mat_compare[m]['mass_kg'] for m in mat_names]
                bar_colors = ['green' if m == mat_var.get() else '#95a5a6' for m in mat_names]
                bars = ax2.barh(mat_names, mat_masses, color=bar_colors, alpha=0.8, edgecolor='black')
                for bar, val in zip(bars, mat_masses):
                    ax2.text(bar.get_width()+0.01, bar.get_y()+bar.get_height()/2,
                            f'{val:.2f} kg', va='center', fontsize=8)
                ax2.set_xlabel('Mass (kg)')
                ax2.set_title('Material Comparison', fontweight='bold')
                ax2.grid(True, alpha=0.3, axis='x')

                ax3 = fig.add_subplot(1, 3, 3)
                ax3.axis('off')
                data = [
                    ['Parameter', 'Value'],
                    ['Material', mat_var.get()[:18]],
                    ['Wall thickness', f"{float(thick_var.get()):.1f} mm"],
                    ['Mass', f"{mass_result['mass_kg']:.3f} kg"],
                    ['Mass', f"{mass_result['mass_lbm']:.3f} lbm"],
                    ['Surface area', f"{mass_result['surface_area_m2']*1e4:.1f} cm²"],
                    ['Volume', f"{mass_result['volume_m3']*1e6:.1f} cm³"],
                    ['Density', f"{mass_result['density_kg_m3']} kg/m³"],
                    ['Thrust/Weight', f"{tw:.1f}" if tw > 0 else 'N/A'],
                    ['Convergent', f"{breakdown.get('Convergent',0):.3f} kg"],
                    ['Throat', f"{breakdown.get('Throat',0):.3f} kg"],
                    ['Divergent', f"{breakdown.get('Divergent',0):.3f} kg"],
                ]
                t = ax3.table(cellText=data, loc='center', cellLoc='center')
                t.auto_set_font_size(False); t.set_fontsize(9); t.scale(1.2, 1.7)
                t[(0,0)].set_facecolor('#1A237E'); t[(0,0)].set_text_props(color='white', weight='bold')
                t[(0,1)].set_facecolor('#1A237E'); t[(0,1)].set_text_props(color='white', weight='bold')
                ax3.set_title('Weight Summary', fontweight='bold', pad=15)

                fig.tight_layout()
                canvas_widget.draw()

            except Exception as e:
                messagebox.showerror("Error", str(e))
                import traceback; traceback.print_exc()

        run_btn.config(command=run_analysis)
