        result_labels['thrust'].grid(row=1, column=2, padx=10, sticky=tk.W)
        
        # Plot frame
        plot_frame = ttk.Frame(sweep_win)
        plot_frame.pack(fill=tk.BOTH, expand=True, padx=10, pady=10)
        
        # Create figure
        fig = Figure(figsize=(14, 6))
        ax_geom = fig.add_subplot(1, 2, 1)
        ax_mach = fig.add_subplot(1, 2, 2)
        
        canvas = FigureCanvasTkAgg(fig, master=plot_frame)
        canvas.get_tk_widget().pack(fill=tk.BOTH, expand=True)
        
        # Update function
        colorbar_ref = [None]  # Store colorbar reference
        
        def update_plot(*args):
            try:
                # Get current values
                mach = float(mach_var.get())
                throat = float(throat_var.get())
                rays = int(float(rays_var.get()))  # Convert to int properly
                gamma = float(gamma_var.get())
                
                # Validate ranges
                if mach < 1.5 or mach > 4.0:
                    return
                if throat < 0.5 or throat > 2.0:
                    return
                if rays < 10 or rays > 60:
                    return
                if gamma < 1.2 or gamma > 1.6:
                    return
                
                # Update labels
                mach_label.config(text=f"{mach:.2f}")
                throat_label.config(text=f"{throat:.3f}")
                rays_label.config(text=f"{rays}")
                gamma_label.config(text=f"{gamma:.3f}")
                
                # Calculate
                engine = MOCEngine(gamma=gamma)
                prob_type = base_params.get('problem_type', 1)
                
                if prob_type == 1:
                    results = engine.calculate_2d_ideal_nozzle(
                        mach_exit=mach,
                        num_rays=rays,
                        throat_height=throat
                    )
                    throat_area = throat * 1.0 / 144.0
                else:
                    results = engine.calculate_axisymmetric_nozzle(
                        mach_exit=mach,
                        num_rays=rays,
                        throat_radius=throat
                    )
                    throat_area = np.pi * (throat / 12.0)**2
                
                # Update result labels
                length = results['wall_x'][-1]
                exit_area = results['wall_y'][-1]
                area_ratio = exit_area / throat
                exit_mach = results.get('exit_mach', mach)
                
                result_labels['length'].config(text=f"Length: {length:.2f} in", foreground='black')
                result_labels['area_ratio'].config(text=f"Area Ratio: {area_ratio:.2f}", foreground='black')
                result_labels['exit_area'].config(text=f"Exit Area: {exit_area:.3f} in", foreground='black')
                result_labels['exit_mach'].config(text=f"Exit Mach: {exit_mach:.3f}", foreground='black')
                
                # Calculate mass flow
                R = 1716.0
                p0 = base_params['p0'] * 144.0
                T0 = base_params['T0']
                mass_flow = (p0 * throat_area / np.sqrt(T0)) * \
                           np.sqrt(gamma / R) * \
                           ((gamma + 1) / 2)**((gamma + 1) / (2 * (gamma - 1)))
                result_labels['mass_flow'].config(text=f"Mass Flow: {mass_flow:.2f} lbm/s", foreground='black')
                
                # Estimate thrust
                thrust = mass_flow * 32.174 * mach * 100  # Simplified
                result_labels['thrust'].config(text=f"Thrust (est): {thrust:.0f} lbf", foreground='black')
                
                # Clear axes
                ax_geom.clear()
                ax_mach.clear()
                
                # Remove old colorbar if exists
                if colorbar_ref[0] is not None:
                    try:
                        colorbar_ref[0].remove()
                    except:
                        pass
                    colorbar_ref[0] = None
                
                # Plot geometry
                wall_x = results['wall_x']
                wall_y = results['wall_y']
                
                ax_geom.plot(wall_x, wall_y, 'b-', linewidth=2, label='Upper Wall')
                ax_geom.plot(wall_x, [-y for y in wall_y], 'b-', linewidth=2, label='Lower Wall')
                ax_geom.fill_between(wall_x, wall_y, [-y for y in wall_y], alpha=0.2, color='blue')
                
                ax_geom.set_xlabel('Axial Position (in)', fontsize=10)
                ax_geom.set_ylabel('Radial Position (in)', fontsize=10)
                ax_geom.set_title('Nozzle Geometry', fontsize=11, fontweight='bold')
                ax_geom.grid(True, alpha=0.3)
                ax_geom.set_aspect('equal')
                ax_geom.legend()
                
                # Plot Mach contour
                try:
                    X, Y, Z_mach = engine.get_contour_data(variable='mach')
                    contour = ax_mach.contourf(X, Y, Z_mach, levels=20, cmap='jet')
                    ax_mach.plot(wall_x, wall_y, 'k-', linewidth=2)
                    ax_mach.plot(wall_x, [-y for y in wall_y], 'k-', linewidth=2)
                    
                    # Create new colorbar and store reference
                    colorbar_ref[0] = fig.colorbar(contour, ax=ax_mach, label='Mach Number')
                    
                    ax_mach.set_xlabel('Axial Position (in)', fontsize=10)
                    ax_mach.set_ylabel('Radial Position (in)', fontsize=10)
                    ax_mach.set_title('Mach Number Distribution', fontsize=11, fontweight='bold')
                    ax_mach.set_aspect('equal')
                except Exception as e2:
                    print(f"Mach contour error: {e2}")
                    ax_mach.text(0.5, 0.5, 'Mach contour unavailable', 
                               ha='center', va='center', transform=ax_mach.transAxes)
                
                fig.tight_layout()
                canvas.draw()
                
            except Exception as e:
                print(f"Update failed: {e}")
                import traceback
                traceback.print_exc()
                
                # Show error in red
                result_labels['length'].config(text="Length: ERROR", foreground='red')
                result_labels['area_ratio'].config(text="Area Ratio: ERROR", foreground='red')
                result_labels['exit_area'].config(text="Exit Area: ERROR", foreground='red')
                result_labels['exit_mach'].config(text="Exit Mach: ERROR", foreground='red')
                result_labels['mass_flow'].config(text="Mass Flow: ERROR", foreground='red')
                result_labels['thrust'].config(text="Thrust (est): ERROR", foreground='red')
        
        
        
        # Initial plot
        update_plot()
        
        # Buttons
        button_frame = ttk.Frame(sweep_win)
        button_frame.pack(fill=tk.X, padx=10, pady=10)
        
        def reset_params():
            mach_var.set(base_params['mach_exit'])
            throat_var.set(base_params['throat_height'])
            rays_var.set(base_params['num_rays'])
            gamma_var.set(base_params['gamma'])
        
        ttk.Button(button_frame, text="Reset to Base", command=reset_params).pack(side=tk.LEFT, padx=5)
        ttk.Button(button_frame, text="Close", command=sweep_win.destroy).pack(side=tk.RIGHT, padx=5)
