            if 'shocks' in results_base:
                base_text.insert(tk.END, f"Shocks: {len(results_base['shocks'])}\n")
            base_text.config(state='disabled')
            
            all_results.append(('BASE', results_base, base_params))
            
            # SCENARIO 1: Higher Mach
