            s3_text.insert(tk.END, f"Length: {results_s3['wall_x'][-1]:.3f} in\n")
            s3_text.insert(tk.END, f"Exit Height: {results_s3['wall_y'][-1]:.3f} in\n")
            s3_text.insert(tk.END, f"Area Ratio: {results_s3['wall_y'][-1]/s3_throat:.3f}\n")
            
            exit_area_change = ((results_s3['wall_y'][-1] - results_base['wall_y'][-1]) / results_base['wall_y'][-1]) * 100
            s3_text.insert(tk.END, f"\nΔ Exit Area: {exit_area_change:+.1f}%\n")
            s3_text.insert(tk.END, f"Note: Larger throat = more mass flow\n")
            s3_text.config(state='disabled')
            
            all_results.append(('S3: +30% Throat', results_s3, s3_params))
            
            # SCENARIO 4: Custom
            s4_text.config(state='normal')
